    if(activeFlowId!=='UIF-06')return base035(state);const req=io06CurrentRequest(),lines=io06CurrentLines();if(state==='UNKNOWN'){const body=ioResult('Đang xác minh kết quả','Không gửi lại thao tác. Hệ thống đang xác minh đúng lần xử lý này; tiếp tục bằng cùng operation identity.',[['Yêu cầu trả',req.id],['Đơn bán',req.source],['Tồn kho','Chưa kết luận']],'warning');const attrs=`data-v350-action="handoff-unknown" data-source-flow="UIF-06" data-operation="${attr(req.operationId)}" data-scope="${attr(req.id+' · '+req.source)}"`;return appShell({title:'Xác minh kết quả',body,centered:true,back:false,actions:primaryFooter('Chuyển sang xác minh',attrs)});}if(state==='REJECTED_EXECUTION')return appShell({title:'Kết quả hàng trả',body:ioResult('Chưa thể ghi nhận','Dữ liệu hiện hành đã thay đổi; tồn kho chưa bị tác động.',[['Yêu cầu trả',req.id],['Đơn bán',req.source],['Tồn kho','Không thay đổi']],'warning'),centered:true,back:false,actions:primaryFooter(req.receiptCommitted?'Xem phần phân loại đã cập nhật':'Xem yêu cầu đã cập nhật',req.receiptCommitted?'data-io06-action="open-classification"':'data-io06-action="back-to-return-request"')});if(state==='PERMISSION_DENIED')return appShell({title:'Kết quả hàng trả',body:ioResult('Không có quyền thực hiện','Tồn kho không thay đổi.',[['Yêu cầu trả',req.id],['Đơn bán',req.source],['Tồn kho','Không thay đổi']],'warning'),centered:true,back:false,actions:primaryFooter('Về Hàng khách trả','data-io06-action="result-to-return-queue"')});
